-- DISPOSABLE local PostgreSQL only. Never execute as a production migration.
DO $$ BEGIN IF current_database() NOT LIKE 'c3_f06_isolated_%' THEN RAISE EXCEPTION 'Refuse nonisolated database'; END IF; END $$;
CREATE TABLE public.messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('visitor','assistant','agent','system')),content text NOT NULL,content_type text DEFAULT 'text' CHECK(content_type IN ('text','image','video','file','quick_reply')),status text DEFAULT 'delivered' CHECK(status IN ('sending','delivered','read','recalled','failed')),is_recalled boolean DEFAULT false,metadata jsonb DEFAULT '{}',created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),sender_id uuid REFERENCES public.agent_profile(id),sender_identity_verified_at timestamptz,sender_identity_source text);
